---@class CResourcesMgr
local CResourcesMgr = T(Global, "CResourcesMgr")
---@type CResources
local Resources = Plugins.Require("resources", "client.data.CResources")
---@type [string, CResources]
local AllResources = {}

function CResourcesMgr:syncResourcesInfo(data)
    for id, info in pairs(data) do
        if AllResources[id] then
            local resources = AllResources[id]
            resources:updateResources(info)
        else
            if TableUtil.getTableSize(AllResources) >= Define.ResourceMax then
                return
            end
            local resources = Resources.new(id, info)
            if resources then
                AllResources[id] = resources
            end
        end
    end
end

function CResourcesMgr:removeResources(id)
    AllResources[tostring(id)] = nil
end

---@return CResources
function CResourcesMgr:getResources(id)
    return AllResources[id]
end

function CResourcesMgr:getResourcesIdByEntityId(entityId)
    for id, resources in pairs(AllResources) do
        if resources:checkEntityId(entityId) then
            return id
        end
    end
    return false
end

return CResourcesMgr